style.css:
@-moz-document domain("pinterest.com") {
/* ? FALL PINTEREST THEME */

    /* Main background */
    html,
    body,
    #app {
        background: #f5eee5 !important;
    }

    /* Pinterest header */
    header {
        background: #f5eee5 !important;
    }

    /* Search bar */
    input {
        background: #e8d9c8 !important;
        color: #4a3427 !important;
    }

    /* General text */
    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        color: #4a3427 !important;
    }

    /* Links */
    a {
        color: #654735 !important;
    }

    /* Buttons */
    button {
        border-radius: 20px !important;
    }

    /* Pinterest cards */
    [data-test-id="pin"] {
        border-radius: 16px !important;
    }

    /* Hover effect */
    [data-test-id="pin"]:hover {
        opacity: 0.92 !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #f5eee5;
    }

    ::-webkit-scrollbar-thumb {
        background: #a85f3e;
        border-radius: 10px;
    }

    /* Pinterest overlays */
    [role="dialog"] {
        background: #fffaf4 !important;
    }
}
